node - <<'"'NODE'
const fs = require('fs');
const vm = require('vm');
const html = fs.readFileSync('index.html', 'utf8');
const script = html.match(/<script>([\\s\\S]*?)<\\/script>/)[1];
const ids = ['stage','timeReadout','phaseReadout','speedReadout','relativeSpeed','gForce','energy','intrusion','systemState','progressBar','liveStatus','replayButton','pauseButton','slowButton'];
const noop = () => {};
const gradient = () => ({ addColorStop: noop });
const ctx = new Proxy({}, { get(target, prop) {
  if (prop === 'createLinearGradient' || prop === 'createRadialGradient') return gradient;
  if (prop === 'measureText') return () => ({ width: 0 });
  if ("'!(prop in target)) target[prop] = noop;
  return target[prop];
}});
const elements = Object.fromEntries(ids.map(id => [id, {
  style: {}, textContent: '"'',
  getContext: id === 'stage' ? () => ctx : undefined,
  getBoundingClientRect: id === 'stage' ? () => ({ width: 960, height: 592 }) : undefined,
  addEventListener: noop,
  setAttribute: noop,
  setPointerCapture: noop,
}]));
elements.stage.width = 1200; elements.stage.height = 740;
const rafs = [];
const windowMock = {
  devicePixelRatio: 1,
  addEventListener: noop,
  requestAnimationFrame: callback => { rafs.push(callback); return rafs.length; },
};
const context = vm.createContext({
  document: { getElementById: id => elements[id] },
  window: windowMock,
  performance: { now: () => 0 },
  requestAnimationFrame: windowMock.requestAnimationFrame,
  HTMLInputElement: function HTMLInputElement() {},
  HTMLTextAreaElement: function HTMLTextAreaElement() {},
  console,
  Math,
});
vm.runInContext(script, context, { timeout: 1000 });
if (typeof context.window.__crashSim?.getState "'!== '"'function') throw new Error('runtime API missing');
const initial = context.window.__crashSim.getState();
if (rafs.length === 0) throw new Error('animation frame not scheduled');
rafs.shift()(16);
const afterFrame = context.window.__crashSim.getState();
context.window.__crashSim.scrubBy(1);
const afterScrub = context.window.__crashSim.getState();
console.log(JSON.stringify({
  fileFetch: 'ok',
  runtimeInit: 'ok',
  initialTime: initial.time,
  frameTime: afterFrame.time,
  scrubbedTime: afterScrub.time,
  scrubPaused: afterScrub.playing === false,
}));
NODE
printf '\\n--- final validation ---\\n'
